-- Dynamic, admin-approved location directory (schema + RPCs).
-- Data is seeded by 0033_locations_seed.sql (generated by
-- scripts/build-locations-seed.js).
--
-- Replaces the hard-coded city list (data/categories.ts `regions`,
-- web/src/lib/categories.ts `cities`, plus the cityCurrency / cityRegion /
-- featuredCities maps) with one table that the mobile app, the web app and the
-- web admin all read.
--
-- Model: three levels in one table.
--   kind = 'country'  a country, or an app-supported region that is not an
--                     internationally recognised sovereign state (Somaliland):
--                     is_app_region marks those. No parent.
--   kind = 'region'   a state / region / province. Parent = country.
--   kind = 'city'     a city, town or locality. Parent = region (or the country
--                     directly when no regions are listed).
--
-- Currencies are data, not code: `currency_codes` lists the currencies sellers
-- may price in at that place and `default_currency` the pre-selected one. They
-- are set on the country and inherited down the tree unless a child overrides.
--
-- Backward compatible: listings keep their `city` / `region` / `currency` text
-- columns exactly as before (deployed app versions keep working). A nullable
-- listings.location_id is maintained by a trigger purely as a link, so
-- renames/merges/approvals can keep the listing's displayed name in sync.
-- Nothing here deletes or rewrites existing listing data except the
-- location_id backfill in 0033.

-- ============================================================================
-- 0. Upgrade from the first draft of this migration (2-level model with
--    `currency` / `region_label` columns). A no-op on a fresh database.
--    Existing rows, ids and listings.location_id links are kept; old cities are
--    re-parented under their regions by 0033.
-- ============================================================================
do $$
begin
  if to_regclass('public.locations') is not null then
    alter table public.locations
      add column if not exists iso2 text,
      add column if not exists currency_codes text[],
      add column if not exists default_currency text,
      add column if not exists name_so text,
      add column if not exists name_am text,
      add column if not exists aliases text[];

    alter table public.locations drop constraint if exists locations_kind_check;
    alter table public.locations drop constraint if exists locations_parent_matches_kind;
    alter table public.locations drop constraint if exists locations_currency_check;
    alter table public.locations drop constraint if exists locations_default_in_codes;
    alter table public.locations drop constraint if exists locations_iso2_check;

    alter table public.locations
      add constraint locations_kind_check check (kind in ('country', 'region', 'city')),
      add constraint locations_parent_matches_kind check ((kind = 'country') = (parent_id is null)),
      add constraint locations_iso2_check check (iso2 is null or iso2 ~ '^[A-Z]{2}$');

    -- Carry the draft's per-country currency over to the new currency lists.
    update public.locations set currency_codes = array['ETB', 'USD'], default_currency = 'ETB', iso2 = 'ET'
      where kind = 'country' and normalized_name = 'ethiopia' and currency_codes is null;
    update public.locations set currency_codes = array['USD', 'SOS'], default_currency = 'USD', iso2 = 'SO'
      where kind = 'country' and normalized_name = 'somalia' and currency_codes is null;
    update public.locations set currency_codes = array['USD', 'SLSH'], default_currency = 'USD'
      where kind = 'country' and normalized_name = 'somaliland' and currency_codes is null;

    alter table public.locations add constraint locations_default_in_codes check (
      default_currency is null or currency_codes is null or default_currency = any (currency_codes)
    );

    alter table public.locations drop column if exists currency;
    alter table public.locations drop column if exists region_label;
  end if;
end $$;

-- Signatures/return types changed since the draft.
drop function if exists public.submit_location_request(text, uuid);
drop function if exists public.admin_list_locations(text);
drop function if exists public.admin_save_location(uuid, text, text, uuid, text, text, boolean, boolean);

-- ============================================================================
-- 1. Table
-- ============================================================================
create or replace function public.normalize_location_name(p_name text)
returns text
language sql
immutable
as $$
  select lower(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g'));
$$;

create table if not exists public.locations (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('country', 'region', 'city')),
  name text not null check (char_length(btrim(name)) between 2 and 80),
  normalized_name text not null,
  parent_id uuid references public.locations (id) on delete restrict,
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected', 'inactive')),
  is_app_region boolean not null default false,
  is_featured boolean not null default false,
  iso2 text check (iso2 is null or iso2 ~ '^[A-Z]{2}$'),
  -- Currencies sellers can choose here (ISO 4217-style codes; SLSH = Somaliland
  -- shilling). Null/empty = inherit from the parent.
  currency_codes text[],
  default_currency text,
  -- Translated display names and extra search spellings. `name` (English) is
  -- the canonical value stored on listings.
  name_so text,
  name_am text,
  aliases text[],
  requested_by uuid references public.profiles (id) on delete set null,
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  rejection_reason text,
  merged_into_id uuid references public.locations (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint locations_parent_matches_kind check ((kind = 'country') = (parent_id is null)),
  constraint locations_default_in_codes check (
    default_currency is null or currency_codes is null or default_currency = any (currency_codes)
  )
);

-- Duplicate prevention: one live record per (kind, parent, normalised name).
-- Rejected rows are excluded so a name can be re-requested later.
create unique index if not exists locations_unique_live_name
  on public.locations (kind, coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), normalized_name)
  where status in ('pending', 'approved', 'inactive');

create index if not exists locations_status_kind_name_idx
  on public.locations (status, kind, name);
create index if not exists locations_normalized_idx
  on public.locations (normalized_name);
create index if not exists locations_parent_idx
  on public.locations (parent_id);

create or replace function public.trg_locations_normalize()
returns trigger
language plpgsql
as $$
declare
  v_parent_kind text;
begin
  new.name := regexp_replace(btrim(new.name), '\s+', ' ', 'g');
  new.normalized_name := public.normalize_location_name(new.name);
  new.updated_at := now();
  if new.parent_id is not null then
    select kind into v_parent_kind from public.locations where id = new.parent_id;
    if (new.kind = 'region' and v_parent_kind is distinct from 'country')
       or (new.kind = 'city' and v_parent_kind not in ('country', 'region')) then
      raise exception 'A % cannot sit under a %', new.kind, coalesce(v_parent_kind, 'missing parent');
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists locations_normalize on public.locations;
create trigger locations_normalize
  before insert or update on public.locations
  for each row execute function public.trg_locations_normalize();

-- Effective currencies for a place: its own list, else the nearest ancestor's.
create or replace function public.location_currency_codes(p_id uuid)
returns text[]
language sql
stable
as $$
  with recursive chain as (
    select id, parent_id, currency_codes, 0 as depth from public.locations where id = p_id
    union all
    select l.id, l.parent_id, l.currency_codes, c.depth + 1
    from public.locations l join chain c on l.id = c.parent_id
  )
  select currency_codes from chain
  where currency_codes is not null and array_length(currency_codes, 1) > 0
  order by depth limit 1;
$$;

create or replace function public.location_default_currency(p_id uuid)
returns text
language sql
stable
as $$
  with recursive chain as (
    select id, parent_id, default_currency, 0 as depth from public.locations where id = p_id
    union all
    select l.id, l.parent_id, l.default_currency, c.depth + 1
    from public.locations l join chain c on l.id = c.parent_id
  )
  select coalesce(
    (select default_currency from chain where default_currency is not null order by depth limit 1),
    (public.location_currency_codes(p_id))[1]
  );
$$;

-- The label stored in listings.region: the nearest region ancestor (or the
-- place itself when it is a region), else the country name.
create or replace function public.location_region_label(p_id uuid)
returns text
language sql
stable
as $$
  with recursive chain as (
    select id, parent_id, kind, name, 0 as depth from public.locations where id = p_id
    union all
    select l.id, l.parent_id, l.kind, l.name, c.depth + 1
    from public.locations l join chain c on l.id = c.parent_id
  )
  select name from chain where kind in ('region', 'country')
  order by (kind = 'country'), depth limit 1;
$$;

-- ============================================================================
-- 2. RLS / grants — public reads approved rows only, no client writes at all.
-- ============================================================================
alter table public.locations enable row level security;

drop policy if exists "approved locations are publicly readable" on public.locations;
create policy "approved locations are publicly readable" on public.locations
  for select using (status = 'approved');
-- Deliberately NO insert/update/delete policy: every write goes through the
-- SECURITY DEFINER functions below.

-- Column-level grant so requester ids, reviewer ids and rejection reasons are
-- never readable through PostgREST even for approved rows.
revoke all on public.locations from anon, authenticated;
grant select (id, kind, name, normalized_name, parent_id, status, is_app_region,
              is_featured, iso2, currency_codes, default_currency, name_so, name_am,
              aliases, created_at, updated_at)
  on public.locations to anon, authenticated;

-- ============================================================================
-- 3. listings.location_id — a maintained link, never a source of truth for
--    display (listings.city text still is, so history survives any edit).
-- ============================================================================
alter table public.listings
  add column if not exists location_id uuid references public.locations (id) on delete set null;

create index if not exists listings_location_id_idx on public.listings (location_id);

-- Resolves listings.city to the most specific matching place (city, then
-- region, then country), preferring approved rows.
create or replace function public.trg_listings_link_location()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' or new.city is distinct from old.city then
    new.location_id := (
      select l.id from public.locations l
      where l.normalized_name = public.normalize_location_name(new.city)
        and l.status in ('approved', 'pending', 'inactive')
      order by (l.status = 'approved') desc,
               (case l.kind when 'city' then 0 when 'region' then 1 else 2 end),
               l.created_at
      limit 1
    );
  end if;
  return new;
end;
$$;

drop trigger if exists listings_link_location on public.listings;
create trigger listings_link_location
  before insert or update of city on public.listings
  for each row execute function public.trg_listings_link_location();

-- ============================================================================
-- 4. submit_location_request — any signed-in user. Reuses an existing record
--    instead of creating duplicates. The caller never sets status/requester.
--    p_parent_id is the region (or country) the new city belongs to.
-- ============================================================================
create or replace function public.submit_location_request(p_name text, p_parent_id uuid)
returns table (id uuid, name text, status text, currency_codes text[], default_currency text, region_label text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_parent public.locations;
  v_existing public.locations;
  v_row public.locations;
begin
  if v_uid is null then
    raise exception 'Sign in to add a location' using errcode = '42501';
  end if;
  if exists (select 1 from public.profiles where profiles.id = v_uid and account_status = 'suspended') then
    raise exception 'Account suspended' using errcode = '42501';
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 80 then
    raise exception 'Location name must be 2-80 characters';
  end if;

  select * into v_parent from public.locations c
  where c.id = p_parent_id and c.kind in ('country', 'region') and c.status = 'approved';
  if not found then
    raise exception 'Choose a valid country or region first';
  end if;

  select * into v_existing from public.locations l
  where l.kind = 'city' and l.parent_id = v_parent.id
    and l.normalized_name = public.normalize_location_name(v_name)
    and l.status in ('approved', 'pending', 'inactive');
  if found then
    return query select v_existing.id, v_existing.name, v_existing.status,
                        public.location_currency_codes(v_existing.id),
                        public.location_default_currency(v_existing.id),
                        public.location_region_label(v_existing.id);
    return;
  end if;

  -- Anti-spam: at most 10 new requests per user per day.
  if (select count(*) from public.locations l
      where l.requested_by = v_uid and l.created_at > now() - interval '1 day') >= 10 then
    raise exception 'Too many location requests today. Please try again tomorrow.' using errcode = '54000';
  end if;

  insert into public.locations (kind, name, parent_id, status, requested_by)
  values ('city', v_name, v_parent.id, 'pending', v_uid)
  returning * into v_row;

  return query select v_row.id, v_row.name, v_row.status,
                      public.location_currency_codes(v_row.id),
                      public.location_default_currency(v_row.id),
                      public.location_region_label(v_row.id);
end;
$$;

grant execute on function public.submit_location_request(text, uuid) to authenticated;

-- ============================================================================
-- 5. Admin RPCs (all gated by is_admin(), all audited)
-- ============================================================================
create or replace function public.admin_list_locations(p_status text default null)
returns table (
  id uuid, kind text, name text, parent_id uuid, parent_name text, status text,
  is_app_region boolean, is_featured boolean, iso2 text, currency_codes text[],
  default_currency text, name_so text, name_am text, aliases text[],
  requested_by uuid, requester_name text, reviewed_at timestamptz,
  rejection_reason text, merged_into_id uuid, created_at timestamptz, listing_count bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Only an admin can list locations' using errcode = '42501';
  end if;
  return query
    select l.id, l.kind, l.name, l.parent_id, p.name, l.status, l.is_app_region, l.is_featured,
           l.iso2, l.currency_codes, l.default_currency, l.name_so, l.name_am, l.aliases,
           l.requested_by, coalesce(pr.full_name, pr.email), l.reviewed_at, l.rejection_reason,
           l.merged_into_id, l.created_at,
           (select count(*) from public.listings li where li.location_id = l.id)
    from public.locations l
    left join public.locations p on p.id = l.parent_id
    left join public.profiles pr on pr.id = l.requested_by
    where p_status is null or l.status = p_status
    order by (case l.kind when 'country' then 0 when 'region' then 1 else 2 end), l.name;
end;
$$;

grant execute on function public.admin_list_locations(text) to authenticated;

-- Create (p_id null → approved immediately) or edit a record. Renaming a place
-- also updates the displayed name on the listings linked to it so the Home
-- filter (which matches on listings.city) stays consistent.
create or replace function public.admin_save_location(
  p_id uuid,
  p_kind text,
  p_name text,
  p_parent_id uuid,
  p_currency_codes text[],
  p_default_currency text,
  p_name_so text,
  p_name_am text,
  p_aliases text[],
  p_is_app_region boolean,
  p_is_featured boolean
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_codes text[] := case when p_currency_codes is null or array_length(p_currency_codes, 1) is null then null
                         else (select array_agg(distinct upper(btrim(c))) from unnest(p_currency_codes) c where btrim(c) <> '') end;
  v_default text := nullif(upper(btrim(coalesce(p_default_currency, ''))), '');
  v_aliases text[] := case when p_aliases is null then null
                           else (select array_agg(distinct btrim(a)) from unnest(p_aliases) a where btrim(a) <> '') end;
  v_parent uuid := p_parent_id;
  v_old public.locations;
  v_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an admin can save locations' using errcode = '42501';
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 80 then
    raise exception 'Name must be 2-80 characters';
  end if;
  if p_kind not in ('country', 'region', 'city') then
    raise exception 'Invalid kind';
  end if;
  if p_kind = 'country' then
    v_parent := null;
  elsif v_parent is null then
    raise exception 'A % needs a parent', p_kind;
  end if;
  if v_codes is not null and exists (select 1 from unnest(v_codes) c where c !~ '^[A-Z]{3,4}$') then
    raise exception 'Currency codes must be 3-4 letters, e.g. USD, ETB, SOS';
  end if;
  if v_default is not null and v_codes is not null and not (v_default = any (v_codes)) then
    raise exception 'The default currency must be one of the allowed currencies';
  end if;

  if p_id is null then
    insert into public.locations (kind, name, parent_id, status, is_app_region, is_featured,
                                  currency_codes, default_currency, name_so, name_am, aliases,
                                  reviewed_by, reviewed_at)
    values (p_kind, v_name, v_parent, 'approved',
            coalesce(p_is_app_region, false), coalesce(p_is_featured, false),
            v_codes, v_default, nullif(btrim(coalesce(p_name_so, '')), ''),
            nullif(btrim(coalesce(p_name_am, '')), ''), v_aliases, auth.uid(), now())
    returning id into v_id;
  else
    select * into v_old from public.locations where id = p_id for update;
    if not found then raise exception 'Location not found'; end if;
    if v_old.kind <> p_kind then raise exception 'Cannot change a location''s kind'; end if;
    if v_parent = p_id then raise exception 'A location cannot be its own parent'; end if;

    update public.locations set
      name = v_name,
      parent_id = v_parent,
      currency_codes = v_codes,
      default_currency = v_default,
      name_so = nullif(btrim(coalesce(p_name_so, '')), ''),
      name_am = nullif(btrim(coalesce(p_name_am, '')), ''),
      aliases = v_aliases,
      is_app_region = coalesce(p_is_app_region, is_app_region),
      is_featured = coalesce(p_is_featured, is_featured)
    where id = p_id;
    v_id := p_id;

    if v_old.name is distinct from v_name then
      update public.listings set city = v_name where location_id = p_id;
    end if;
  end if;

  insert into public.admin_audit_log (admin_id, action, target_type, target_id, metadata)
  values (auth.uid(), case when p_id is null then 'create_location' else 'edit_location' end,
          'location', v_id::text, jsonb_build_object('name', v_name, 'kind', p_kind));
  return v_id;
end;
$$;

grant execute on function public.admin_save_location(uuid, text, text, uuid, text[], text, text, text, text[], boolean, boolean) to authenticated;

-- approve | reject | deactivate | reactivate | delete
create or replace function public.admin_review_location(
  p_id uuid,
  p_action text,
  p_reason text default null,
  p_new_name text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_loc public.locations;
  v_name text;
begin
  if not public.is_admin() then
    raise exception 'Only an admin can review locations' using errcode = '42501';
  end if;
  select * into v_loc from public.locations where id = p_id for update;
  if not found then raise exception 'Location not found'; end if;

  if p_action = 'approve' then
    if v_loc.status <> 'pending' then raise exception 'Only pending requests can be approved'; end if;
    v_name := coalesce(nullif(regexp_replace(btrim(coalesce(p_new_name, '')), '\s+', ' ', 'g'), ''), v_loc.name);
    if exists (
      select 1 from public.locations o
      where o.id <> v_loc.id and o.kind = v_loc.kind
        and o.parent_id is not distinct from v_loc.parent_id
        and o.normalized_name = public.normalize_location_name(v_name)
        and o.status in ('approved', 'inactive', 'pending')
    ) then
      raise exception 'A location named "%" already exists here. Merge this request into it instead.', v_name;
    end if;
    update public.locations
      set status = 'approved', name = v_name, reviewed_by = auth.uid(), reviewed_at = now(),
          rejection_reason = null
      where id = p_id;
    -- Keep listings that used the submitted spelling in sync with the canonical name.
    if v_name is distinct from v_loc.name then
      update public.listings set city = v_name where location_id = p_id;
    end if;

  elsif p_action = 'reject' then
    if v_loc.status <> 'pending' then raise exception 'Only pending requests can be rejected'; end if;
    update public.locations
      set status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(),
          rejection_reason = nullif(btrim(coalesce(p_reason, '')), '')
      where id = p_id;

  elsif p_action = 'deactivate' then
    if v_loc.status <> 'approved' then raise exception 'Only approved locations can be deactivated'; end if;
    update public.locations set status = 'inactive', reviewed_by = auth.uid(), reviewed_at = now() where id = p_id;

  elsif p_action = 'reactivate' then
    if v_loc.status <> 'inactive' then raise exception 'Only inactive locations can be reactivated'; end if;
    update public.locations set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now() where id = p_id;

  elsif p_action = 'delete' then
    -- Hard delete only when nothing references the row; otherwise deactivate.
    if v_loc.status in ('approved') then raise exception 'Deactivate an approved location before deleting it'; end if;
    if exists (select 1 from public.listings where location_id = p_id)
       or exists (select 1 from public.locations where parent_id = p_id) then
      raise exception 'This location is still used by listings or child locations. Deactivate it instead.';
    end if;
    delete from public.locations where id = p_id;

  else
    raise exception 'Unknown action: %', p_action;
  end if;

  insert into public.admin_audit_log (admin_id, action, target_type, target_id, reason, metadata)
  values (auth.uid(), p_action || '_location', 'location', p_id::text, p_reason,
          jsonb_build_object('name', v_loc.name, 'newName', p_new_name));
end;
$$;

grant execute on function public.admin_review_location(uuid, text, text, text) to authenticated;

-- Merge a duplicate (usually a pending request) into an existing city.
create or replace function public.admin_merge_location(p_id uuid, p_target_id uuid, p_reason text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_src public.locations;
  v_dst public.locations;
begin
  if not public.is_admin() then
    raise exception 'Only an admin can merge locations' using errcode = '42501';
  end if;
  if p_id = p_target_id then raise exception 'Cannot merge a location into itself'; end if;
  select * into v_src from public.locations where id = p_id for update;
  select * into v_dst from public.locations where id = p_target_id for update;
  if v_src.id is null or v_dst.id is null then raise exception 'Location not found'; end if;
  if v_src.kind <> 'city' or v_dst.kind <> 'city' then
    raise exception 'Only cities can be merged, and only with another city';
  end if;
  if v_dst.status not in ('approved', 'inactive') then
    raise exception 'Merge target must be an approved location';
  end if;

  -- Mark the source rejected first so the listings trigger resolves the new
  -- name to the target.
  update public.locations
    set status = 'rejected', merged_into_id = v_dst.id, reviewed_by = auth.uid(), reviewed_at = now(),
        rejection_reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Merged into ' || v_dst.name)
    where id = v_src.id;

  update public.listings set city = v_dst.name, location_id = v_dst.id where location_id = v_src.id;

  insert into public.admin_audit_log (admin_id, action, target_type, target_id, reason, metadata)
  values (auth.uid(), 'merge_location', 'location', v_src.id::text, p_reason,
          jsonb_build_object('from', v_src.name, 'into', v_dst.name, 'intoId', v_dst.id));
end;
$$;

grant execute on function public.admin_merge_location(uuid, uuid, text) to authenticated;
